mapper.sql:
execution_row.task_id = #{filter.taskId}

  AND (execution_row.normalized_link LIKE CONCAT('%', #{filter.keyword}, '%')
    OR execution_row.group_jid LIKE CONCAT('%', #{filter.keyword}, '%'))


  AND execution_row.execution_status = #{filter.executionStatus}


  AND execution_row.stage = #{filter.stage}


  AND execution_row.wait_resource_type = #{filter.waitResourceType}


  AND execution_row.manual_paused = #{filter.manualPaused}
